"""Passive Root publishers for fixed probes and prospective prefix custody.

No resource or ID is selected at import. Root calls these only after all gates.
Each job has an immutable CREATED reference before START and positive own END.
"""
import datetime, hashlib, json, os, pathlib, re, stat, uuid

SOURCE='mecanet-qa-p1l3-r03';TARGET=SOURCE+'-target';BUSINESS={'api1','api2','worker','web'}
HASH=re.compile(r'^[a-f0-9]{64}$');SHA=re.compile(r'^[a-f0-9]{40}$');UUID=re.compile(r'^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$')
SCHEMA_SQL={'pre':75,'post':9};FAULT_POINT='PROMOTION_AFTER_OPEN_A'
def check(ok,code):
 if not ok:raise AssertionError(code)
def canonical(value):return json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode()
def digest(value):return hashlib.sha256(value if isinstance(value,bytes) else canonical(value)).hexdigest()
def stamp():return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec='milliseconds').replace('+00:00','Z')
def ended_at(value):
 try:return datetime.datetime.fromisoformat(value.replace('Z','+00:00')).timestamp() if isinstance(value,str) and value.endswith('Z') and not value.startswith('0001-') else None
 except ValueError:return None
def schema_case(mode):check(mode in SCHEMA_SQL,'PROBE_SCHEMA_MODE');return 'source-schema-probe-'+mode
def read(h,path,uid=0,mode=0o400,limit=262144,json_value=True):return h.target_bridge().read_private(path,uid,limit,mode,json_value)
def publish(h,path,value,uid=0,limit=262144):
 raw=canonical(value);check(2<=len(raw)<=limit,'PROBE_INPUT_SIZE')
 if path.exists() or path.is_symlink():
  old,sha=read(h,path,uid,limit=limit);check(old==value and sha==digest(value),'PROBE_IMMUTABLE_CONFLICT');return sha
 h.write_plain(path,raw,0o400,uid);old,sha=read(h,path,uid,limit=limit);check(old==value and sha==digest(value),'PROBE_INPUT_READBACK');return sha
def namespace(h,variant=False):
 check(h.ROOT==pathlib.Path('/opt')/SOURCE,'PROBE_NAMESPACE')
 check(h.TARGET==pathlib.Path('/opt')/TARGET if not variant else getattr(h,'kind',None)=='promote-prefix' and h.TARGET==pathlib.Path('/opt')/TARGET/'variants/promote-prefix','PROBE_NAMESPACE')
 h.own(h.ROOT);h.own(h.TARGET);h.preserve();h.guard_resources(h.facts(),[],h.expected_owners())
def budget(h,case,scope,sql=0):
 state,sh=read(h,h.ROOT/'budget/ledger.json',999,0o600);now=h.uptime();check(state.get('schema')=='cp019-budget-v1' and state.get('project')==SOURCE and 0<=now-state['startedUptime']<=1800 and state.get('plannedScopes',{}).get(case)==scope and state.get('plannedScenarios',{}).get(case)==h.CASE_LIMITS,'PROBE_BUDGET')
 check(set(state['total'])==set(h.CEILINGS) and all(type(n) is int and 0<=n<=h.CEILINGS[k] for k,n in state['total'].items()) and state['total']['sql']+sql<=h.CEILINGS['sql'],'PROBE_BUDGET')
 old=state.get('scenarios',{}).get(case)
 if old is not None:check(old['limits']==h.CASE_LIMITS and 0<=now-old['startedUptime']<45 and set(old['total'])==set(h.CASE_LIMITS) and all(type(n) is int and 0<=n<=h.CASE_LIMITS[k] for k,n in old['total'].items()) and old['total']['sql']+sql<=h.CASE_LIMITS['sql'],'PROBE_CASE_EXPIRED')
def enter(h,case,scope,sql=0):
 budget(h,case,scope,sql);h.set_host_case(case);h.enter_runtime_case(scope,case)
def artifact(h,m):
 a,ah=read(h,h.ROOT/'staging/artifact.json',0,0o444);check(SHA.fullmatch(a.get('sourceSha','')) and a.get('digest')=='sha256:'+m['artifactDigest'] and digest(a['entries'])==m['artifactDigest'],'PROBE_ARTIFACT');return a
def migration_hashes(h,a):
 out={}
 for scope,name in [('central','006-control-recovery.sql'),('tenant','006-tenant-recovery.sql')]:
  path='server/saas/db/migrations/'+name;entries=[x for x in a['entries'] if x['path']==path];check(len(entries)==1 and HASH.fullmatch(entries[0].get('sha256','')),'PROBE_MIGRATION_ENTRY');raw,rh=read(h,h.ROOT/'staging'/path,0,0o444,262144,False);check(rh==entries[0]['sha256'] and len(raw)==entries[0]['bytes'],'PROBE_MIGRATION_HASH');out[scope]=rh
 return out
def make_schema_config(m,r,source_sha,hashes,ca,mode,invocation):
 schema_case(mode);check(UUID.fullmatch(invocation or '') and SHA.fullmatch(source_sha or '') and set(hashes)=={'central','tenant'} and all(HASH.fullmatch(x or '') for x in hashes.values()) and isinstance(ca,str) and 0<len(ca)<=65536,'PROBE_SCHEMA_INPUT')
 check(r.get('project')==SOURCE and r.get('generation')==m['source']['generation'] and r.get('networkIP')=='10.77.64.2' and r.get('dataPath')=='/opt/'+SOURCE+'/data/18/docker' and HASH.fullmatch(r.get('containerId','')) and re.fullmatch('[0-9]{10,24}',r.get('systemIdentifier','')),'PROBE_SCHEMA_RESOURCE')
 return {'schema':'cp020-schema-fault-input-v1','project':SOURCE,'mode':mode,'sourceSha':source_sha,'invocationId':invocation,'custodyHash':digest(m),'resource':r,'migrationHashes':hashes,'adminConnection':{'host':'postgres','port':5432,'database':'postgres','user':'qa_bootstrap','password':m['source']['rolePasswords']['qa_bootstrap'],'ssl':{'ca':ca,'servername':'postgres','rejectUnauthorized':True}}}
def make_credential_config(m,bindings,invocation):
 check(UUID.fullmatch(invocation or '') and m['target']['project']==TARGET and bindings.get('custodyHash')==digest(m) and SHA.fullmatch(bindings.get('sourceSha','')) and all(HASH.fullmatch(bindings.get(k,'')) for k in ['configBundleHash','configBundleHeaderHash']),'PROBE_CREDENTIAL_INPUT')
 return {'schema':'cp020-credential-probe-config-v1','project':TARGET,'invocationId':invocation,**{k:bindings[k] for k in ['sourceSha','custodyHash','configBundleHash','configBundleHeaderHash']}}
def schema_packet(cfg,observed,observed_at):
 check(set(observed)=={'resource','sourcePostgresRunning','targetPostgresRunning','runtimeConsumers'} and observed['resource']==cfg['resource'] and observed['sourcePostgresRunning'] is True and observed['targetPostgresRunning'] is False and observed['runtimeConsumers']==[],'PROBE_SCHEMA_RESOURCES')
 body={'schema':'cp020-schema-probe-host-v1','caseName':schema_case(cfg['mode']),'mode':cfg['mode'],'invocationId':cfg['invocationId'],'sourceSha':cfg['sourceSha'],'custodyHash':cfg['custodyHash'],'resourceHash':digest(cfg['resource']),'observedAt':observed_at,'observedResources':observed};return {'receipt':body,'receiptHash':digest(body)}
def schema_observation(h,cfg):
 check(h.source_resource()['resource']==cfg['resource'],'PROBE_SOURCE_RESOURCE_CHANGED');current=h.facts();h.guard_resources(current,[],h.expected_owners());own=[c for c in current if c.get('project') in [SOURCE,TARGET] and c.get('running')];check(not any(c.get('service') in BUSINESS or c.get('project')==TARGET for c in own),'PROBE_SOURCE_NOT_EXCLUSIVE');pgs=[c for c in own if c.get('service')=='postgres'];check(len(pgs)==1 and pgs[0]['id']==cfg['resource']['containerId'] and h.owned_identity(pgs[0],h.expected_owners()),'PROBE_SOURCE_PG_CHANGED')
 return schema_packet(cfg,{'resource':cfg['resource'],'sourcePostgresRunning':True,'targetPostgresRunning':False,'runtimeConsumers':[]},stamp())
def schema_mailbox(h,packet):
 check(set(packet)=={'receipt','receiptHash'} and packet['receiptHash']==digest(packet['receipt']) and packet['receipt'].get('schema')=='cp020-schema-probe-host-v1','PROBE_SCHEMA_MAILBOX');directory=h.ROOT/'live';s=directory.lstat();check(directory.resolve()==directory and not directory.is_symlink() and stat.S_ISDIR(s.st_mode) and s.st_uid==999 and s.st_mode&0o777==0o700,'PROBE_MAILBOX_DIRECTORY');raw=canonical(packet);check(len(raw)<=262144,'PROBE_MAILBOX_SIZE');h.ledger_charge('artifactFiles');temporary=directory/('.source-schema-'+uuid.uuid4().hex+'.tmp');fd=os.open(temporary,os.O_WRONLY|os.O_CREAT|os.O_EXCL|getattr(os,'O_NOFOLLOW',0),0o400)
 try:
  with os.fdopen(fd,'wb',closefd=False) as f:f.write(raw);f.flush();os.fchmod(fd,0o400);os.fchown(fd,999,999);os.fsync(fd)
  os.close(fd);fd=None;os.replace(temporary,directory/'source-schema-host.json');h.syncdir(directory)
 finally:
  if fd is not None:os.close(fd)
  if temporary.exists():temporary.unlink()
 saved,sha=read(h,directory/'source-schema-host.json',999);check(saved==packet and sha==digest(packet),'PROBE_MAILBOX_READBACK')
def own_end(h,job,proof,command,project):
 created,ch=read(h,job['root']/'evidence/jobs'/(job['jobId']+'-created.json'));ended,eh=read(h,job['root']/'evidence/jobs'/(job['jobId']+'-end.json'))
 check(ch==job['receiptHash']==proof['jobCreatedHash'] and eh==proof['jobEndHash'] and proof.get('containerFIN')=='PASS' and proof.get('sqlFIN')=='NOT VERIFIED' and created.get('schema')=='controller-job-created-v1' and created.get('state')=='CREATED BEFORE START/SQL' and created.get('commandHash')==digest(command) and created.get('jobId')==job['jobId'] and created.get('containerId')==job['cid']==proof['containerId'] and created.get('project')==project and created.get('ownerId')==job['ownerId'],'PROBE_OWN_CREATED')
 times=[ended_at(created.get('createdAt')),ended_at(ended.get('startedAt')),ended_at(ended.get('finishedAt'))]
 check(ended.get('schema')=='controller-job-end-v1' and all(ended.get(k)==created[k] for k in ['jobId','containerId','project','service','ownerId']) and ended.get('createdReceiptHash')==ch and ended.get('exitCode')==0 and ended.get('containerStopped') is True and ended.get('sqlAbsence')=='NOT VERIFIED' and all(t is not None for t in times) and times==sorted(times),'PROBE_OWN_END');return ch,eh
def run_job(h,root,profile,command,env,mounts,update=lambda:None):
 check(UUID.fullmatch(env.get('QA_INVOCATION_ID','')) and not (root/'evidence/jobs'/(env['QA_INVOCATION_ID']+'-created.json')).exists(),'PROBE_ORIGINAL_JOB_RECONCILIATION_REQUIRED');h.guard_effect(root,[profile]);update();job=h.create_job(root,profile,command,env,mounts=mounts,sample=False);check(job['jobId']==env['QA_INVOCATION_ID'],'PROBE_JOB_INVOCATION');update();h.start_job(job);output,proof=h.target_bridge().watch_job(h,job,update);own_end(h,job,proof,command,env['QA_PROJECT']);return json.loads(output),job,proof
def config_once(h,path,make):
 if path.exists() or path.is_symlink():old,sha=read(h,path);check(old==make(old['invocationId']),'PROBE_CONFIG_CHANGED');return old
 value=make(str(uuid.uuid4()));publish(h,path,value);return value
def schema_probe(h,mode):
 case=schema_case(mode);namespace(h);enter(h,case,'source-window',SCHEMA_SQL[mode]);m=h.material_owned();a=artifact(h,m);resource=h.source_resource()['resource'];hashes=migration_hashes(h,a);ca,_=read(h,h.ROOT/'config/ca.crt',0,0o444,65536,False);master=h.ROOT/'master'/('schema-probe-'+mode+'-config.json');cfg=config_once(h,master,lambda inv:make_schema_config(m,resource,a['sourceSha'],hashes,ca.decode(),mode,inv));alias=h.ROOT/'secrets'/('schema-probe-'+mode+'-'+cfg['invocationId']+'.json');publish(h,alias,cfg,999)
 report_path=h.ROOT/'evidence'/('source-schema-probe-'+mode+'.json');check(not report_path.exists() and not report_path.is_symlink(),'PROBE_ALREADY_REPORTED_KEEP');command=['node','tests/qa/cp019/schema-fault-probe.mjs',mode];update=lambda:schema_mailbox(h,schema_observation(h,cfg));env={'QA_PROJECT':SOURCE,'QA_CODE_SHA':a['sourceSha'],'QA_INVOCATION_ID':cfg['invocationId']};result,job,proof=run_job(h,h.ROOT,'harness',command,env,[(alias,'/run/qa-secrets/schema-fault-probe.json','ro'),(h.ROOT/'live','/run/qa-live','ro')],update)
 report,rh=read(h,report_path,999);check(result=={'type':'cp020-schema-fault-probe','mode':mode,'status':'PASS','reportHash':rh,'secretsPrinted':False} and report.get('schema')=='cp020-schema-fault-report-v1' and report.get('status')=='PASS' and report.get('mode')==mode and report.get('caseName')==case and report.get('custodyHash')==cfg['custodyHash'] and report.get('resourceHash')==digest(resource) and report.get('sourceSha')==cfg['sourceSha'] and report.get('sqlCommands')==SCHEMA_SQL[mode] and report.get('permanentChanges')==0,'PROBE_SCHEMA_REPORT');record={'schema':'cp021-schema-probe-host-result-v1','mode':mode,'caseName':case,'configHash':digest(cfg),'reportHash':rh,'invocationId':cfg['invocationId'],'jobProof':proof};publish(h,h.ROOT/'master'/('schema-probe-'+mode+'-result.json'),record);return {'result':'PASS FOR OWN SCHEMA PROBE ONLY',**record,'physicalAcceptance':'NOT VERIFIED'}
def phase_receipt(h,phase,base,bindings):
 receipt,rh=read(h,h.TARGET/'evidence'/('target-'+phase+'.json'),999);m=h.material_owned();check(receipt.get('schema')=='target-runtime-receipt-v1' and receipt.get('phase')==phase and receipt.get('planHash')==base['planHash'] and receipt.get('generation')==m['target']['generation'] and receipt.get('recoveryId')==m['recoveryId'] and all(receipt.get(k)==bindings[k] for k in ['custodyHash','configBundleHash','sourceSha']),'PROBE_PHASE_REQUIRED');command=['node','tests/qa/cp019/target-runtime.mjs','run',phase];matching=[]
 for path in (h.TARGET/'evidence/jobs').glob('*-created.json'):
  c,ch=read(h,path)
  if c.get('commandHash')==digest(command) and c.get('ownerId')==m['controllerOwner'] and c.get('project')==TARGET:matching.append((c,ch))
 check(len(matching)==1,'PROBE_PHASE_OWN_JOB_REQUIRED');c,ch=matching[0];job={'root':h.TARGET,'cid':c['containerId'],'jobId':c['jobId'],'ownerId':c['ownerId'],'receiptHash':ch};end,eh=read(h,h.TARGET/'evidence/jobs'/(c['jobId']+'-end.json'));own_end(h,job,{'containerId':job['cid'],'jobCreatedHash':ch,'jobEndHash':eh,'containerFIN':'PASS','sqlFIN':'NOT VERIFIED'},command,TARGET);raw,logh=read(h,h.TARGET/'evidence/jobs'/(c['jobId']+'-output.log'),999,json_value=False);output=json.loads(raw);check(output.get('type')=='cp019-target-phase' and output.get('phase')==phase and output.get('planHash')==base['planHash'] and output.get('receiptHash')==rh and output.get('secretOutput') is False and (not callable(getattr(h,'variant_lineage',None)) or receipt.get('variantLineageHash')==base.get('variantLineageHash')),'PROBE_PHASE_OUTPUT_BINDING');return receipt,rh
def credential_probe(h):
 namespace(h);check(not callable(getattr(h,'variant_frame',None)),'PROBE_CREDENTIAL_MAIN_ONLY');enter(h,'target-credential-negatives','target-window',54);m,base,bindings=h.target_bridge().bundle_context(h);phase_receipt(h,'rotate',base,bindings);snapshot,sh=journal_snapshot(h);check(not (h.TARGET/'evidence/target-canary.json').exists() and all(r.get('operationId')!=m['stageOperationIds']['target-canary'] for r in snapshot['records']),'PROBE_CREDENTIAL_BEFORE_CANARY');check(not any(c.get('project') in [SOURCE,TARGET] and c.get('running') and c.get('service') in BUSINESS for c in h.facts()),'PROBE_CREDENTIAL_RUNTIME_ACTIVE');check(h.target_bridge().target_resource(h)==base['manifest']['target'],'PROBE_CREDENTIAL_RESOURCE')
